(function () {
  "use strict";

  const form      = document.getElementById("consent-form");
  const field     = document.getElementById("field-consent");
  const checkbox  = document.getElementById("consent");
  const errorMsg  = document.getElementById("consent-error");
  const submitBtn = document.getElementById("btn-submit");
  const btnLabel  = document.getElementById("btn-label");
  const status    = document.getElementById("form-status");

  function showFieldError() {
    field.classList.add("form-field--error");
    checkbox.setAttribute("aria-invalid", "true");
    checkbox.setAttribute("aria-describedby", "consent-helper consent-error");
  }

  function clearFieldError() {
    field.classList.remove("form-field--error");
    checkbox.setAttribute("aria-invalid", "false");
    checkbox.setAttribute("aria-describedby", "consent-helper");
  }

  function setStatus(type, message) {
    status.className = "status-banner";
    status.classList.add("status-banner--" + type, "is-visible");
    status.querySelector(".status-banner__text").textContent = message;
  }

  function clearStatus() {
    status.className = "status-banner";
    status.querySelector(".status-banner__text").textContent = "";
  }

  /* Validate on change so error clears as soon as checked */
  checkbox.addEventListener("change", function () {
    if (checkbox.checked) {
      clearFieldError();
    }
  });

  form.addEventListener("submit", async function (e) {
    e.preventDefault();
    clearStatus();

    if (!checkbox.checked) {
      showFieldError();
      checkbox.focus();
      return;
    }

    clearFieldError();

    /* Simulate async submission */
    submitBtn.setAttribute("aria-busy", "true");
    btnLabel.textContent = "Submitting…";
    submitBtn.disabled = true;

    await new Promise((resolve) => setTimeout(resolve, 1400));

    submitBtn.setAttribute("aria-busy", "false");
    submitBtn.disabled = false;
    btnLabel.textContent = "Agree & Continue";

    setStatus(
      "success",
      "You've agreed to the Terms of Use. Welcome aboard!"
    );
    status.querySelector("svg use, svg")?.focus?.();
    /* Move focus to the banner so screen readers announce it */
    status.setAttribute("tabindex", "-1");
    status.focus();
  });
