+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --color-bg: #f5f4f2;
+  --color-surface: #ffffff;
+  --color-border: #d1cfc9;
+  --color-border-focus: #4f46e5;
+  --color-text-primary: #1a1917;
+  --color-text-secondary: #6b6966;
+  --color-accent: #4f46e5;
+  --color-accent-hover: #4338ca;
+  --color-accent-active: #3730a3;
+  --color-error: #b91c1c;
+  --color-error-bg: #fef2f2;
+  --color-success: #166534;
+  --color-success-bg: #f0fdf4;
+  --color-focus-ring: #4f46e5;
+  --radius-sm: 6px;
+  --radius-md: 10px;
+  --radius-lg: 16px;
+  --shadow-card: 0 1px 3px rgba(0,0,0,.08), 0 8px 24px rgba(0,0,0,.06);
+  --font: "Inter", system-ui, -apple-system, sans-serif;
+}
+
+body {
+  font-family: var(--font);
+  background: var(--color-bg);
+  color: var(--color-text-primary);
+  min-height: 100dvh;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  padding: 1.5rem;
+}
+
+/* ── Skip link ─────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -999px;
+  left: 1rem;
+  background: var(--color-accent);
+  color: #fff;
+  padding: .5rem 1rem;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+}
+.skip-link:focus {
+  top: 1rem;
+}
+
+/* ── Card ──────────────────────────────────────────── */
+.card {
+  background: var(--color-surface);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-card);
+  padding: 2.5rem 2rem;
+  width: 100%;
+  max-width: 440px;
+}
+
+.card__brand {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-bottom: 1.75rem;
+}
+
+.card__brand-icon {
+  width: 32px;
+  height: 32px;
+  background: var(--color-accent);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  flex-shrink: 0;
+}
+
+.card__brand-icon svg {
+  fill: #fff;
+}
+
+.card__brand-name {
+  font-size: .9375rem;
+  font-weight: 700;
+  letter-spacing: -.01em;
+  color: var(--color-text-primary);
+}
+
+.card__heading {
+  font-size: 1.375rem;
+  font-weight: 700;
+  letter-spacing: -.02em;
+  line-height: 1.3;
+  margin-bottom: .375rem;
+}
+
+.card__subheading {
+  font-size: .9rem;
+  color: var(--color-text-secondary);
+  line-height: 1.5;
+  margin-bottom: 2rem;
+}
+
+/* ── Divider ───────────────────────────────────────── */
+.divider {
+  border: none;
+  border-top: 1px solid var(--color-border);
+  margin-bottom: 1.75rem;
+}
+
+/* ── Form ──────────────────────────────────────────── */
+form {
+  display: flex;
+  flex-direction: column;
+  gap: 1.25rem;
+}
+
+/* ── form-field (checkbox variant) ────────────────── */
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: .25rem;
+}
+
+.form-field__row {
+  display: flex;
+  align-items: flex-start;
+  gap: .75rem;
+}
+
+/* Custom checkbox */
+.form-field__checkbox-wrap {
+  position: relative;
+  flex-shrink: 0;
+  width: 18px;
+  height: 18px;
+  margin-top: .15rem;
+}
+
+.form-field__checkbox-wrap input[type="checkbox"] {
+  appearance: none;
+  -webkit-appearance: none;
+  width: 18px;
+  height: 18px;
+  border: 1.5px solid var(--color-border);
+  border-radius: 4px;
+  background: var(--color-surface);
+  cursor: pointer;
+  transition: border-color .15s, background .15s, box-shadow .15s;
+  display: block;
+}
+
+.form-field__checkbox-wrap input[type="checkbox"]:hover {
+  border-color: var(--color-accent);
+}
+
+.form-field__checkbox-wrap input[type="checkbox"]:focus-visible {
+  outline: 2px solid var(--color-focus-ring);
+  outline-offset: 2px;
+  /* transparent outline so it shows in forced-colors mode */
+  box-shadow: 0 0 0 3px rgba(79,70,229,.18);
+}
+
+.form-field__checkbox-wrap input[type="checkbox"]:checked {
+  background: var(--color-accent);
+  border-color: var(--color-accent);
+}
+
+/* Checkmark SVG overlay */
+.form-field__checkbox-wrap .checkmark {
+  pointer-events: none;
+  position: absolute;
+  inset: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  opacity: 0;
+  transition: opacity .1s;
+}
+
+.form-field__checkbox-wrap input[type="checkbox"]:checked ~ .checkmark {
+  opacity: 1;
+}
+
+.form-field__checkbox-wrap .checkmark svg {
+  fill: none;
+  stroke: #fff;
+  stroke-width: 2.2;
+  stroke-linecap: round;
+  stroke-linejoin: round;
+}
+
+/* Label + helper */
+.form-field__label-group {
+  display: flex;
+  flex-direction: column;
+  gap: .2rem;
+}
+
+.form-field__label {
+  font-size: .9375rem;
+  font-weight: 500;
+  line-height: 1.4;
+  cursor: pointer;
+  color: var(--color-text-primary);
+}
+
+.form-field__label a {
+  color: var(--color-accent);
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+
+.form-field__label a:hover,
+.form-field__label a:focus-visible {
+  color: var(--color-accent-hover);
+}
+
+.form-field__helper {
+  font-size: .8125rem;
+  color: var(--color-text-secondary);
+  line-height: 1.45;
+}
+
+/* Error state */
+.form-field--error .form-field__checkbox-wrap input[type="checkbox"] {
+  border-color: var(--color-error);
+}
+
+.form-field__error-msg {
+  display: none;
+  font-size: .8125rem;
+  color: var(--color-error);
+  font-weight: 500;
+  align-items: center;
+  gap: .3rem;
+}
+
+.form-field--error .form-field__error-msg {
+  display: flex;
+}
+
+/* ── Submit button ─────────────────────────────────── */
+.btn-submit {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: .5rem;
+  background: var(--color-accent);
+  color: #fff;
+  font-family: inherit;
+  font-size: .9375rem;
+  font-weight: 600;
+  padding: .75rem 1.25rem;
+  border: none;
+  border-radius: var(--radius-md);
+  cursor: pointer;
+  width: 100%;
+  transition: background .15s, transform .1s, box-shadow .15s;
+  letter-spacing: -.01em;
+  margin-top: .25rem;
+}
+
+.btn-submit:hover {
+  background: var(--color-accent-hover);
+}
+
+.btn-submit:active {
+  background: var(--color-accent-active);
+  transform: translateY(1px);
+}
+
+.btn-submit:focus-visible {
+  outline: 2px solid var(--color-focus-ring);
+  outline-offset: 2px;
+  box-shadow: 0 0 0 4px rgba(79,70,229,.2);
+}
+
+.btn-submit[aria-busy="true"] {
+  opacity: .8;
+  cursor: wait;
+}
+
+.btn-submit__spinner {
+  display: none;
+  width: 16px;
+  height: 16px;
+  border: 2px solid rgba(255,255,255,.4);
+  border-top-color: #fff;
+  border-radius: 50%;
+  animation: spin .65s linear infinite;
+}
+
+.btn-submit[aria-busy="true"] .btn-submit__spinner {
+  display: block;
+}
+
+@keyframes spin {
+  to { transform: rotate(360deg); }
+}
+
+/* ── Status banner (success / error) ──────────────── */
+.status-banner {
+  display: none;
+  border-radius: var(--radius-md);
+  padding: .875rem 1rem;
+  font-size: .9rem;
+  font-weight: 500;
+  line-height: 1.4;
+  align-items: flex-start;
+  gap: .625rem;
+}
+
+.status-banner[aria-live] {
+  /* always in DOM so AT can pick up announcements */
+}
+
+.status-banner--success {
+  background: var(--color-success-bg);
+  color: var(--color-success);
+  border: 1px solid #bbf7d0;
+}
+
+.status-banner--error {
+  background: var(--color-error-bg);
+  color: var(--color-error);
+  border: 1px solid #fecaca;
+}
+
+.status-banner.is-visible {
+  display: flex;
+}
+
+.status-banner svg {
+  flex-shrink: 0;
+  margin-top: .1rem;
+}
+
+/* ── Forced-colors support ─────────────────────────── */
+@media (forced-colors: active) {
+  .form-field__checkbox-wrap input[type="checkbox"]:checked {
+    background: ButtonText;
+    border-color: ButtonText;
+  }
+  .form-field__checkbox-wrap .checkmark svg {
+    stroke: ButtonFace;
+  }
+  .btn-submit {
+    border: 2px solid ButtonText;
+  }
+}
+
+/* ── Reflow at 320 px ──────────────────────────────── */
+@media (max-width: 360px) {
+  .card {
+    padding: 1.75rem 1.25rem;
+  }
+}
+
')

